# -*- coding: utf-8 -*-
"""Original Japanese Listening scripts for the N2-MOCK-14 draft."""
from __future__ import annotations

import random
from scripts.curriculum.bank_data.n2_mock_14_explanations_vi import apply_vietnamese_explanations


def _question(qid, type_id, category, script, stem, choices, key_index,
              explanation_vi, *, topic="comprehensive-challenge", difficulty=2):
    width = 3 if type_id == "N2-LIS-RESP" else 4
    if len(choices) != width or not 0 <= key_index < width:
        raise ValueError(f"Invalid M14 listening item: {qid}")
    indexed = list(enumerate(choices))
    _rng.shuffle(indexed)
    letters = "ABCD"
    options = [{"id": letters[pos], "text": text} for pos, (_, text) in enumerate(indexed)]
    key = letters[next(pos for pos, (source, _) in enumerate(indexed) if source == key_index)]
    return {
        "id": qid, "level": "N2", "typeId": type_id, "category": category,
        "script": script, "contextPassage": script, "stem": stem,
        "options": options, "correctAnswer": key,
        "explanation": f"正解は「{choices[key_index]}」です。",
        "explanationVi": explanation_vi,
        "distractorExplanations": {
            option["id"]: f"Phương án «{option['text']}» không khớp với điều kiện, ý định hoặc kết luận nghe được. {explanation_vi}"
            for option in options if option["id"] != key
        },
        "topicTag": topic, "difficultyBand": difficulty, "skill": "Listening",
    }


